import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`competitor-research`,heroTitle:`Know your competitors in minutes`,heroSubtitle:`Perplexity Computer researches every competitor, compares pricing and features, and builds your entire competitive strategy automatically.`,inputUrlCta:`Start analysis`,inputUrlPrefill:`Go to {url} and run a full competitive analysis. Identify all major competitors in this space. For each competitor, research their pricing tiers, key features, target audience, and market positioning. Build a side-by-side feature and pricing comparison matrix. Create a competitive positioning map showing where each player wins and loses. Finally, generate sales battlecards for each competitor with objection handling, key differentiators, and talking points my team can use.`,heroOverlaySteps:[`Researching every competitor on pricing, features, and positioning`,`Building a side-by-side feature matrix and pricing comparison`,`Mapping where you win and lose on a competitive positioning map`,`Battlecards with objection handling and talking points, ready for your team`],generatingSteps:[`Visiting {url} to understand your product, pricing, and positioning`,`Designing an agent to identify and research every competitor in your space`,`Setting up side-by-side feature and pricing comparison pipelines`,`Configuring battlecard templates with objection handling and talking points`],featureSectionTitle:`From research to strategy`,featureCardTitles:[`Understands your market`,`Strategy you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Computer connects to your tools and researches across the web to learn your industry, competitors, and positioning.`,`Feature matrices. Pricing comparisons. Battlecards. Positioning maps. Computer delivers competitive intelligence your team can use immediately.`],capabilitySectionTitle:`Your competitive intelligence team`,capabilitySectionSubtitle:`Point it at your website, get back a complete competitive strategy.`,capabilityCards:[{title:`Competitor Deep Dives`,description:`Computer researches every competitor — pricing pages, feature lists, customer reviews, team size — and summarizes it all in minutes.`},{title:`Feature & Pricing Matrix`,description:`Computer builds a side-by-side comparison of features, pricing tiers, and packaging across every competitor in your space.`},{title:`Positioning Maps`,description:`Computer maps where you win and lose against each competitor — so you know exactly where to double down and where to differentiate.`},{title:`Sales Battlecards`,description:`Computer generates battlecards with objection handling, competitive talking points, and win/loss insights — ready for your sales team.`},{title:`Knows Your Market`,description:`Computer remembers your competitors, positioning, and industry across sessions — so every analysis builds on what it already knows.`},{title:`Ongoing Monitoring`,description:`Computer watches competitor websites, pricing, and reviews — and alerts you when something changes.`}]});export{t as default};
